def main():
    data = Path(__file__).resolve().parent.parent / "data"
    lessons, questions = [], []
    for block_id, title, rule, examples, note, choices, statements, sentence, prompt in TOPICS:
        for index, (name, text) in enumerate([("Правило", rule), ("Примеры в контексте", examples), ("На что обратить внимание", note)], 1):
            lessons.append({"id": f"{block_id}_{index:02}", "block_id": block_id, "order_num": index,
                            "title": f"{name}: {title}" if index == 1 else name, "theory": text})
        tasks = []
        for question, options, correct, explanation in choices:
            tasks.append(("choice", {"question": question, "options": options, "correct": correct}, explanation))
        for question, correct, explanation in statements:
            tasks.append(("boolean", {"question": question, "correct": correct}, explanation))
        tasks.append(("constructor", {"question": prompt, "words": sentence, "correct_order": sentence},
                      "Правильный порядок: " + " ".join(sentence) + "."))
        for index, (kind, payload, explanation) in enumerate(tasks, 1):
            questions.append({"id": f"{block_id}_q{index:02}", "block_id": block_id, "question_type": kind,
                              "payload": json.dumps(payload, ensure_ascii=False), "explanation": explanation})
    for filename, rows in [("grammar_lessons.csv", lessons), ("grammar_questions.csv", questions)]:
        with (data / filename).open("w", encoding="utf-8", newline="") as stream:
            writer = csv.DictWriter(stream, fieldnames=rows[0].keys())
            writer.writeheader()
            writer.writerows(rows)
    print(f"Wrote {len(lessons)} lessons and {len(questions)} questions in {len(TOPICS)} blocks.")


if __name__ == "__main__":
    main()
